REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

# Run from the repo root so the library's relative ENV_FILE (.env) and every
# path below resolve there, wherever the wizard was invoked from. An explicit
# ENV_FILE=... override still works, because the library honours it.
cd "$REPO_ROOT"

# supabase_dashboard PATH builds a dashboard link for the new project.
# SUPABASE_URL is the API origin (https://<ref>.supabase.co), not the dashboard,
# so the project ref is pulled out of it and the dashboard host used instead.
# Falls back to the project list if the ref cannot be read.
supabase_dashboard() {
  local ref="${SUPABASE_URL#*://}"
  ref="${ref%%.*}"
  if [[ -z "$ref" || "$ref" == "$SUPABASE_URL" ]]; then
    printf 'https://supabase.com/dashboard/projects'
  else
    printf 'https://supabase.com/dashboard/project/%s/%s' "$ref" "$1"
  fi
}

# require_env_ignored refuses to continue if .env is tracked. Ticket 20 asks
# for this before anything is written there. It uses `git check-ignore`, which
# only reads: this wizard runs no git command that changes the repository.
# Where a commit or a push is needed, it says what to commit and waits (stage 6).
require_env_ignored() {
  if ! command -v git >/dev/null 2>&1; then
    warn "git not found, so the ignore check cannot run automatically."
    say "Check by hand that .env is listed in .gitignore."
    if ! confirm "Is .env gitignored?"; then
      warn "Stopping: .env must be gitignored before it holds real keys."
      exit 1
    fi
    return 0
  fi
  if (cd "$REPO_ROOT" && git check-ignore -q .env) 2>/dev/null; then
    note "✓ .env is gitignored, so it is safe to write keys into it."
    return 0
  fi
  warn ".env is NOT gitignored. Refusing to write keys into a tracked file."
  say "Add '.env' to .gitignore, then re-run this wizard."
  exit 1
}

